package app.layan.test;
import android.app.*;import android.content.*;import android.content.res.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.hardware.*;import android.location.*;import dalvik.system.DexClassLoader;import java.io.*;import java.lang.reflect.*;import java.util.*;import app.layan.quran.qibla.*;
/** Runs against the installed APK on API 29; no production test hooks or fixed locations. */
public final class QiblaRegression extends Instrumentation {
 private Bundle args;private final StringBuilder report=new StringBuilder();private int assertions;
 public void onCreate(Bundle a){super.onCreate(a);args=a;if(a!=null&&"true".equals(a.getString("diagnosticSoftwareWindow"))){Application app=(Application)getTargetContext().getApplicationContext();app.registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity activity,Bundle state){if(activity.getClass().getName().equals("app.layan.quran.QiblaActivity")){activity.getWindow().getDecorView().setLayerType(View.LAYER_TYPE_SOFTWARE,null);log("DIAGNOSTIC: native window uses a software Canvas layer to isolate GPU text-shader compilation.");}}public void onActivityStarted(Activity activity){}public void onActivityResumed(Activity activity){}public void onActivityPaused(Activity activity){}public void onActivityStopped(Activity activity){}public void onActivitySaveInstanceState(Activity activity,Bundle state){}public void onActivityDestroyed(Activity activity){}});}start();}
 private void check(boolean ok,String message){assertions++;if(!ok)throw new AssertionError(message);}
 private void log(String s){report.append(s).append('\n');android.util.Log.i("LayanQiblaTest",s);}
 private Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 private void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 private void invoke(Object o,String name,Class<?> parameter,Object value)throws Exception{Method m=o.getClass().getDeclaredMethod(name,parameter);m.setAccessible(true);m.invoke(o,value);}
 private void invoke(Object o,String name)throws Exception{Method m=o.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(o);}
 private String texts(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText()).append('\n');if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(texts(((ViewGroup)v).getChildAt(i)));return s.toString();}
 private void shot(Activity a,String name)throws Exception{SystemClock.sleep(300);Bitmap b=NativeScreens.capture(this,a);log("Screenshot "+name+": "+NativeScreens.lastMode);File f=new File(a.getExternalFilesDir("tests"),name);f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
 private void settle(){runOnMainSync(()->{});SystemClock.sleep(150);}
 private Button calibrationButton(Activity activity){final Button[] found={null};long deadline=SystemClock.elapsedRealtime()+30000;while(found[0]==null&&SystemClock.elapsedRealtime()<deadline){runOnMainSync(()->{for(View root:android.view.inspector.WindowInspector.getGlobalWindowViews()){if(root==activity.getWindow().getDecorView())continue;View candidate=root.findViewById(android.R.id.button1);if(candidate instanceof Button&&candidate.isShown()&&candidate.getWidth()>0&&candidate.getHeight()>0){found[0]=(Button)candidate;break;}}});if(found[0]==null)SystemClock.sleep(100);}return found[0];}
 private Activity launch(){log("Launching Qibla activity");ActivityMonitor monitor=addMonitor("app.layan.quran.QiblaActivity",null,false);getTargetContext().startActivity(new Intent().setClassName(getTargetContext(),"app.layan.quran.QiblaActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity a=waitForMonitorWithTimeout(monitor,90000);removeMonitor(monitor);log("Qibla activity launch monitor returned");if(a==null)throw new AssertionError("Qibla launch timed out");settle();return a;}
 private Location location(double lat,double lon){Location l=new Location("instrumentation");l.setLatitude(lat);l.setLongitude(lon);l.setAltitude(25);l.setAccuracy(20);l.setTime(System.currentTimeMillis());return l;}
 private void prepare(){getTargetContext().getSharedPreferences("layan_qibla",0).edit().clear().putBoolean("calib_intro_shown",true).putBoolean("location_asked",true).commit();}
 private void noPermission()throws Exception{prepare();Activity a=launch();settle();SystemClock.sleep(1500);check(field(a,"target")==null,"Denied location must not produce coordinates or Qibla target");QiblaDial dial=(QiblaDial)field(a,"dial");check(dial.renderer().getClass().getField("G").get(dial.renderer())==null,"Denied location has no target marker");check(!dial.renderer().getClass().getField("H").getBoolean(dial.renderer()),"Denied location has no directional needle");String content=texts(a.getWindow().getDecorView()).toLowerCase(Locale.ROOT);check(content.contains("location")||content.contains("الموقع"),"Permission explanation missing");shot(a,"qibla-location-denied.png");runOnMainSync(a::finish);log("Location denied: screen stayed running, permission explanation shown, no default destination direction.");}
 private void mathOracle()throws Exception{Context c=getTargetContext();DexClassLoader original=new DexClassLoader("/data/local/tmp/qibla-reference.apk",c.getCodeCacheDir().getPath(),null,Context.class.getClassLoader());Class<?> fragment=original.loadClass("j1.f");Method calculate=fragment.getMethod("R",Location.class);double[][] points={{30.0444,31.2357},{31.2001,29.9187},{51.5074,-.1278},{-33.8688,151.2093},{40.7128,-74.006},{35.6762,139.6503},{-33.9249,18.4241},{-6.2088,106.8456},{-23.5505,-46.6333},{21.4225,39.8262},{89.9,0},{-41.3,174.78}};
  for(double[] p:points){Location l=location(p[0],p[1]);Object oracle=fragment.getConstructor().newInstance();try{calculate.invoke(oracle,l);}catch(InvocationTargetException e){check(e.getCause() instanceof IllegalStateException||e.getCause() instanceof NullPointerException,"Unexpected reference calculation error "+e.getCause());}QiblaMath.Target ours=QiblaMath.target(l,System.currentTimeMillis());float bearing=fragment.getField("h0").getFloat(oracle),distance=fragment.getField("i0").getFloat(oracle),declination=fragment.getField("j0").getFloat(oracle);check(Math.abs(QiblaMath.turn(bearing,ours.bearing))<0.0001f,"Reference bearing "+Arrays.toString(p));check(Math.abs(distance-ours.distance)<.01,"Reference distance "+Arrays.toString(p));check(Math.abs(declination-ours.declination)<.001,"Reference declination "+Arrays.toString(p));}
  for(int degree=0;degree<360;degree+=3){float[] g={0,0,9.81f};double r=Math.toRadians(degree);float[] m={(float)(-50*Math.sin(r)),(float)(50*Math.cos(r)),-15};check(Math.abs(QiblaMath.turn(degree,QiblaMath.heading(g,m,Surface.ROTATION_0,0)))<.001,"Synthetic sensor heading "+degree);}
  int[] rotations={Surface.ROTATION_0,Surface.ROTATION_90,Surface.ROTATION_180,Surface.ROTATION_270};float[] expected={0,90,180,270};for(int i=0;i<4;i++)check(Math.abs(QiblaMath.turn(expected[i],QiblaMath.heading(new float[]{0,0,9.81f},new float[]{0,50,-15},rotations[i],0)))<.001,"Display rotation "+i);
  check(QiblaMath.facing(0,355)&&QiblaMath.facing(0,5),"Inclusive five degree tolerance");check(!QiblaMath.facing(0,354.9f)&&!QiblaMath.facing(0,5.1f),"Outside five degree tolerance");check(QiblaMath.turn(5,355)==10&&QiblaMath.turn(355,5)==-10,"North crossing turn direction");float[] filter={0,0,0};QiblaMath.filter(filter,new float[]{10,20,30});check(Math.abs(filter[0]-.29999971f)<1e-7,"Original sensor filter weight");log("Original APK bearing/distance/declination matched at 12 global positions. Synthetic headings: 120 directions, four display rotations, north crossing and five-degree alignment boundaries passed.");
 }
 private void ui()throws Exception{Context c=getTargetContext();prepare();for(String lang:new String[]{args!=null&&"ar".equals(args.getString("mode"))?"ar-EG":"en-US"}){check(Resources.getSystem().getConfiguration().getLocales().get(0).getLanguage().equals(lang.startsWith("ar")?"ar":"en"),"Run this UI test after setting the emulator phone language to "+lang);Activity a=launch();settle();SystemClock.sleep(1000);runOnMainSync(()->{try{SensorManager manager=(SensorManager)field(a,"sensors");manager.unregisterListener((SensorEventListener)a);invoke(a,"stopLocation");}catch(Exception e){throw new RuntimeException(e);}});settle();SystemClock.sleep(1000);runOnMainSync(()->{try{set(a,"gravityReady",false);set(a,"magneticReady",false);set(a,"magneticAccuracy",SensorManager.SENSOR_STATUS_ACCURACY_HIGH);invoke(a,"acceptLocation",Location.class,location(30.0444,31.2357));QiblaMath.Target target=(QiblaMath.Target)field(a,"target");invoke(a,"acceptHeading",float.class,target.bearing);}catch(Exception e){throw new RuntimeException(e);}});settle();check((Boolean)field(a,"facing"),"Aligned state "+lang+" sensor="+field(a,"sensorAvailable")+" ready="+field(a,"headingReady")+" heading="+field(a,"trueHeading")+" accuracy="+field(a,"magneticAccuracy")+" target="+field(a,"target")+" text="+texts(a.getWindow().getDecorView()));String text=texts(a.getWindow().getDecorView());log("Locale requested="+lang+" system="+Resources.getSystem().getConfiguration().getLocales()+" activity="+a.getResources().getConfiguration().getLocales()+" bound="+field(a,"locale"));check(text.contains(lang.startsWith("ar")?"القبلة":"Qibla"),"Locale label "+lang+": "+text);check(text.contains(lang.startsWith("ar")?"مكة":"Makkah"),"Distance info "+lang);shot(a,"qibla-2d-"+lang+".png");
   runOnMainSync(()->{try{QiblaMath.Target target=(QiblaMath.Target)field(a,"target");invoke(a,"acceptHeading",float.class,target.bearing-45);}catch(Exception e){throw new RuntimeException(e);}});check(texts(a.getWindow().getDecorView()).contains(lang.startsWith("ar")?"يمين":"right"),"Turn right hint");runOnMainSync(()->{try{QiblaMath.Target target=(QiblaMath.Target)field(a,"target");invoke(a,"acceptHeading",float.class,target.bearing+45);}catch(Exception e){throw new RuntimeException(e);}});check(texts(a.getWindow().getDecorView()).contains(lang.startsWith("ar")?"يسار":"left"),"Turn left hint");
   runOnMainSync(()->{try{invoke(a,"toggleTilt");}catch(Exception e){throw new RuntimeException(e);}});SystemClock.sleep(750);settle();QiblaDial dial=(QiblaDial)field(a,"dial");check(dial.renderer().getWidth()>200&&dial.renderer().getWidth()==dial.renderer().getHeight(),"Compass must fill a square instead of collapsing");check(c.getSharedPreferences("layan_qibla",0).getBoolean("compass_3d",false),"3D preference saved");check(dial.renderer().getClass().getField("I").getFloat(dial.renderer())>.99,"3D tilt completed");shot(a,"qibla-3d-"+lang+".png");
   runOnMainSync(()->{try{invoke(a,"settings");}catch(Exception e){throw new RuntimeException(e);}});settle();check(field(a,"listener")==null,"Settings stops foreground location listener");String settings=texts(a.getWindow().getDecorView());check(!settings.toLowerCase(Locale.ROOT).contains("reminder")&&!settings.contains("تذكير"),"Unrelated reminder settings imported");shot(a,"qibla-settings-"+lang+".png");runOnMainSync(()->{try{invoke(a,"calibrate");}catch(Exception e){throw new RuntimeException(e);}});settle();Button calibrationOk=calibrationButton(a);check(calibrationOk!=null,"Calibration dialog OK button exists after actual layout");shot(a,"qibla-calibration-"+lang+".png");boolean[] dismissed={false};runOnMainSync(()->dismissed[0]=calibrationOk.performClick());check(dismissed[0],"Calibration dialog OK button dismisses the app dialog");settle();runOnMainSync(a::onBackPressed);settle();check(c.getSharedPreferences("layan_qibla",0).getBoolean("compass_3d",false),"3D preserved after settings");
   runOnMainSync(()->{try{invoke(a,"stopSensors");invoke(a,"stopLocation");}catch(Exception e){throw new RuntimeException(e);}});settle();SystemClock.sleep(1000);runOnMainSync(()->{try{set(a,"sensorAvailable",false);invoke(a,"updateStatus");}catch(Exception e){throw new RuntimeException(e);}});log("Missing-sensor fixture: stopped real sensor/location streams after returning from settings.");check(((TextView)field(a,"heading")).getText().toString().equals("—"),"No magnetic sensor must not show orientation");check(!((QiblaDial)field(a,"dial")).renderer().getClass().getField("H").getBoolean(((QiblaDial)field(a,"dial")).renderer()),"No magnetic sensor must not show Qibla needle");shot(a,"qibla-no-sensor-"+lang+".png");java.util.concurrent.CountDownLatch closed=new java.util.concurrent.CountDownLatch(1);Application.ActivityLifecycleCallbacks closeObserver=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity x,Bundle b){}public void onActivityStarted(Activity x){}public void onActivityResumed(Activity x){}public void onActivityPaused(Activity x){}public void onActivityStopped(Activity x){if(x==a)closed.countDown();}public void onActivitySaveInstanceState(Activity x,Bundle b){}public void onActivityDestroyed(Activity x){if(x==a)closed.countDown();}};a.getApplication().registerActivityLifecycleCallbacks(closeObserver);log("Finishing Qibla and awaiting native stop callback");new Handler(Looper.getMainLooper()).post(a::finish);check(closed.await(30,java.util.concurrent.TimeUnit.SECONDS),"Closing section delivers native stop/destroy callback");a.getApplication().unregisterActivityLifecycleCallbacks(closeObserver);check(!(Boolean)field(a,"active")&&field(a,"listener")==null,"Closing section stops updates after actual lifecycle delivery");c.getSharedPreferences("layan_qibla",0).edit().putBoolean("compass_3d",false).commit();log("Qibla 2D/3D, settings, calibration guide, directional hints, missing sensor and lifecycle passed in "+lang+".");}
 }
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_OK;try{if(args!=null&&"denied".equals(args.getString("mode")))noPermission();else if(args!=null&&"math".equals(args.getString("mode")))mathOracle();else if(args!=null&&("ui".equals(args.getString("mode"))||"ar".equals(args.getString("mode"))))ui();else{mathOracle();ui();}out.putString("result",args!=null&&"true".equals(args.getString("diagnosticSoftwareWindow"))?"DIAGNOSTIC":"PASS");}catch(Throwable e){code=Activity.RESULT_CANCELED;log(android.util.Log.getStackTraceString(e));out.putString("error",e.toString());}log("Assertions: "+assertions);try{File f=new File(getTargetContext().getExternalFilesDir("tests"),args!=null&&"denied".equals(args.getString("mode"))?"qibla-denied.log":"qibla-regression-"+(args!=null&&"ar".equals(args.getString("mode"))?"ar":"en")+".log");f.getParentFile().mkdirs();try(FileOutputStream stream=new FileOutputStream(f)){stream.write(report.toString().getBytes("UTF-8"));}}catch(Exception ignored){}out.putString("report",report.toString());finish(code,out);}
}
